svg.script:
(()=>{
  const root=document.documentElement;
  const reduced=matchMedia("(prefers-reduced-motion: reduce)").matches;
  if(reduced){root.pauseAnimations();root.setCurrentTime(7.7);root.removeAttribute("tabindex");return}
  const restart=()=>{root.setCurrentTime(0);root.unpauseAnimations()};
  root.addEventListener("click",restart);
  root.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();restart()}});
  document.addEventListener("visibilitychange",()=>document.hidden?root.pauseAnimations():root.unpauseAnimations());
})();
